INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1503962-acct311', 'stk-user9840', 'ACCT 311', 'info', '{"desc": "من اهم الكورسات لطلاب الاكاونتينق لانه باختصار هذا هو اللي بتشتغله لو رحت البيق فور او مكاتب المحاسبة .\n\nCOURSE OUTCOMES\n\nAudit function and its environment\nAuditor’s legal, professional and ethical responsibilities\nAudit process and possible problems faced during an audit\nEngagement letter, its preparation and implications\nWorking papers and evidence gathering\nInternal controls and its implications for the audit\nPlanning and modifying the audit engagement\nSampling techniques and their effect on the efficiency and effectiveness of the audit\nPerforming compliance and substantive tests\nEvaluation of audit findings and preparation of the audit report.\n**COURSE OBJECTIVES **\n\nThe subject is designed to provide students, who are majoring in accountancy, with professional, theoretical and practical knowledge that is needed by accountants in understanding and discharging their responsibilities as auditors in a professional environment. This includes the legal, professional and ethical requirements.\n\nThe main general objectives of this subject are for the students to:\n\nKnow, understand, the nature of auditing and its environment\nUnderstand and observe auditors’ legal, professional and ethical responsibilities in performing audit\nUnderstand and prepare the engagement letter\nRealize the importance of working papers and evidence gathering and prepare the necessary working papers needed during an engagement.\nEvaluate the internal control system of the auditee and consider its impact on compliance and substantive tests\nPlan and modify the audit engagement in the audit engagement in the light of the nature of the audit and legal requirements\nPerform sampling techniques and understand their effect on the efficiency and effectiveness of theaudit\nPerform compliance and substantive test\nEvaluate the audit findings and prepare the audit report.\nChs:\n\nThe Role of the Public Accountant in the American Economy\n\nThe Role of the Public Accountant in the American Economy\n\nProfessional Standards\n\nProfessional Ethics\n\nLegal Liability of CPAs\n\nAudit Evidence and Documentation\n\nMidterm Exam, (Chapters 1-5)\n\n(Date and Time will be announced)\n\nPlanning the Audit: Linking Audit Procedures and Risk\n\nInternal Control\n\nConsideration of Internal Control in an Information Technology Audit\n\nAudit Sampling\n\nCash and Financial Investments\n\nAccounts Receivables, Notes Receivables and Revenue\n\nProperty, Plant, and Equipment: Depreciation and Depletion\n\nAuditing Operations and Completing the Audit\n\nAudit Report", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/acct-311-auditing/120968/2", "user": "user9840", "ts": 1545554515000, "tid": 120968, "pn": 2}}', 1545554515000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9921-acct311', 'stk-user9921', 'ACCT 311', 'doc', '{"docs": [{"id": "stk-dr-f98419", "n": "Dr. Muhammad Shahidulislam", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Acct 311\n172\n\nالتحضير :\nغالباً آخر المحاضرة ولو عندك عذر أو حاجة بلّغه من قبل وما رح يغيّبك\n\nطريقة الشرح :\nحل مسائل وشرح على السلايدات وفي اللاب تطبيق عملي …\n\nالمياجر و الفاينلات:\nيعطي Study Guide إذا درسته راح يكفيك للاختبار\n\nالقريد النهائي:\nB+\n\nالصوت:\nواضح واكسنته زي الاجانب مو تعبانه زي باقي الهنود\n\nإضافات :\nدكتور طيب ومتساعد واذا واجهت مشكلة روح له", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1492570-acct311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muhammad-shahidulislam/98419/11", "user": "user9921", "ts": 1526548529000, "tid": 98419, "pn": 11}}]}', 1526548529000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-khdsa2022-acct311', 'stk-khdsa2022', 'ACCT 311', 'doc', '{"docs": [{"id": "stk-dr-f98419", "n": "Dr. Muhammad Shahidulislam", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "BY WHATSAPP\nاسم الدكتور : شهيد الاسلام\nالمادة: ACCT311\nالفصل الدراسي: 191\nبنود التقييم ⬇️⬇️⬇️\n\nالتحضير : بشكل يومي لكنه متسامح\nطريقة الشرح : شرحه من السلايدات و يضيف بعض التعليقات الخارجية والمهمة ، ايضا بعض المحاضرات يقوم بدعوة احد الموظفين من الشركات الاربع الاودتنق ويشرحوا\nالكويزات : ٤ كويزات ، نوعين :\nالاول اختيارات ومقالي\nالثاني اختيارات فقط\nالمياجر: اخذنا ميد عن ٥ فصول ، كان متعلق بالكتاب واسئلته ، حاول تذاكر مبكر لانه المادة مهمة\nالفاينلات : نفس الميد\nالقريد النهائي: للدكتور A+\nالصوت: ممتاز و مفهوم بشكل كبير\nإضافات : حاول انك تفهم المادة لانها مهمة بالمستقبل ، ايضا الدكتور ما يقصر معك لكن حاول ما تقصر معه وبإذن الله تطلع بقريد ممتاز", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518868-acct311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muhammad-shahidulislam/98419/18", "user": "Khdsa2022", "ts": 1578313541000, "tid": 98419, "pn": 18}}]}', 1578313541000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-kbsc-acct311', 'stk-kbsc', 'ACCT 311', 'doc', '{"docs": [{"id": "stk-dr-f98423", "n": "Dr. Abdullah D. Alharbi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اسم الدكتور : *\n\nعبدالله الحربي\n\nالمادة: *\n\nACCT 311\n\nطريقة الشرح : *\n\nسلايدات\n\nالكويزات :\n\nما فيه كويزات\n\nالمياجر/ميد:\n\nTB\n\nطريقة التحضير :\n\nعادةً يحضّر بداية الكلاس\nالقريد النهائي الخاص بك :\n\nإحتمال B or B+\nاضافات:\n\nالدكتور طيّب و لكن أسلوبه ممل + أسلوبه لا يمت الأكاديمية بأي صلة .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1507358-acct311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-abdullah-d-alharbi/98423/20", "user": "KBSC", "ts": 1552816628000, "tid": 98423, "pn": 20}}]}', 1552816628000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
